import csv
import json
import glob
import os

DESC_PATH = '/root/data/stock-descriptions.csv'
HIST_DIR = '/root/data/indiv-stock'
OUT_PATH = '/root/output/js/visualization.js'

# Load stock descriptions
stocks = []
with open(DESC_PATH, newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        market_cap = None
        if row.get('marketCap'):
            try:
                market_cap = float(row['marketCap'])
            except ValueError:
                market_cap = None
        stocks.append({
            'ticker': row.get('ticker', '').strip(),
            'sector': row.get('sector', '').strip(),
            'name': row.get('full name', '').strip(),
            'marketCap': market_cap,
        })

stocks.sort(key=lambda d: d['ticker'])

# Load price history
price_history = {}
for path in sorted(glob.glob(os.path.join(HIST_DIR, '*.csv'))):
    ticker = os.path.basename(path).split('.')[0]
    rows = []
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            date = row.get('Date')
            close = row.get('Close')
            if not date or not close:
                continue
            try:
                close_val = float(close)
            except ValueError:
                continue
            rows.append([date, close_val])
    rows.sort(key=lambda r: r[0])
    price_history[ticker] = rows

stock_json = json.dumps(stocks, ensure_ascii=True)
price_json = json.dumps(price_history, ensure_ascii=True)

template = """/*
  Deterministic D3 v6 visualization.
  Data embedded from /root/data/stock-descriptions.csv and /root/data/indiv-stock
  to keep the file:// experience working without a local server.
*/

const STOCK_DATA = __STOCK_DATA__;
const PRICE_HISTORY = __PRICE_HISTORY__;

(() => {
  const data = STOCK_DATA.map((d) => ({
    ticker: d.ticker,
    sector: d.sector,
    name: d.name,
    marketCap: Number.isFinite(d.marketCap) ? d.marketCap : null
  }));

  data.sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker));

  const sectors = Array.from(new Set(data.map((d) => d.sector))).sort();
  const color = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10.slice(0, sectors.length));

  const capValues = data.map((d) => d.marketCap).filter((d) => d !== null);
  const minCap = d3.min(capValues);
  const maxCap = d3.max(capValues);
  const radiusScale = d3.scaleSqrt()
    .domain([minCap, maxCap])
    .range([14, 52]);

  data.forEach((d) => {
    d.isETF = d.sector === 'ETF' || d.marketCap === null;
    d.radius = d.isETF ? 18 : radiusScale(d.marketCap);
  });

  const width = 700;
  const height = 520;

  const svg = d3.select('#bubble-chart')
    .append('svg')
    .attr('viewBox', `0 0 ${width} ${height}`)
    .attr('role', 'img')
    .attr('aria-label', 'Bubble chart showing sector clusters sized by market cap.');

  const centerRadius = Math.min(width, height) * 0.25;
  const sectorCenters = new Map();
  sectors.forEach((sector, i) => {
    const angle = (i / sectors.length) * Math.PI * 2;
    sectorCenters.set(sector, {
      x: width / 2 + Math.cos(angle) * centerRadius,
      y: height / 2 + Math.sin(angle) * centerRadius
    });
  });

  const nodesBySector = d3.group(data, (d) => d.sector);
  for (const [sector, nodes] of nodesBySector.entries()) {
    const center = sectorCenters.get(sector);
    const sorted = nodes.slice().sort((a, b) => d3.ascending(a.ticker, b.ticker));
    const cols = Math.ceil(Math.sqrt(sorted.length));
    sorted.forEach((d, i) => {
      const row = Math.floor(i / cols);
      const col = i % cols;
      d.x = center.x + (col - cols / 2) * 12;
      d.y = center.y + (row - cols / 2) * 12;
    });
  }

  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX((d) => sectorCenters.get(d.sector).x).strength(0.2))
    .force('y', d3.forceY((d) => sectorCenters.get(d.sector).y).strength(0.2))
    .force('collide', d3.forceCollide((d) => d.radius + 1.5))
    .stop();

  for (let i = 0; i < 260; i += 1) {
    simulation.tick();
  }

  const node = svg.append('g')
    .attr('class', 'nodes')
    .selectAll('g')
    .data(data)
    .enter()
    .append('g')
    .attr('class', 'node')
    .attr('transform', (d) => `translate(${d.x}, ${d.y})`);

  node.append('circle')
    .attr('r', (d) => d.radius)
    .attr('fill', (d) => color(d.sector));

  node.append('text')
    .attr('class', 'node-label')
    .attr('text-anchor', 'middle')
    .attr('dy', '0.35em')
    .style('font-size', (d) => `${Math.max(9, Math.min(14, d.radius * 0.5))}px`)
    .text((d) => d.ticker);

  const legend = svg.append('g')
    .attr('class', 'legend')
    .attr('transform', `translate(${width - 180}, 24)`);

  const legendItems = legend.selectAll('g')
    .data(sectors)
    .enter()
    .append('g')
    .attr('transform', (d, i) => `translate(0, ${i * 20})`);

  legendItems.append('circle')
    .attr('r', 6)
    .attr('cx', 0)
    .attr('cy', 0)
    .attr('fill', (d) => color(d));

  legendItems.append('text')
    .attr('x', 12)
    .attr('y', 4)
    .text((d) => d);

  const tooltip = d3.select('#tooltip');

  node.on('mouseover', (event, d) => {
    if (d.isETF) {
      return;
    }
    tooltip
      .classed('visible', true)
      .html(`<strong>${d.ticker}</strong><br/>${d.name}<br/>${d.sector}`)
      .style('left', `${event.pageX + 12}px`)
      .style('top', `${event.pageY - 24}px`);
  })
    .on('mousemove', (event, d) => {
      if (d.isETF) {
        return;
      }
      tooltip
        .style('left', `${event.pageX + 12}px`)
        .style('top', `${event.pageY - 24}px`);
    })
    .on('mouseout', () => {
      tooltip.classed('visible', false);
    });

  const table = d3.select('#stock-table');
  const thead = table.append('thead');
  const tbody = table.append('tbody');

  thead.append('tr')
    .selectAll('th')
    .data(['Ticker symbol', 'Full company name', 'Sector', 'Market cap'])
    .enter()
    .append('th')
    .text((d) => d);

  const formatMarketCap = (value) => {
    if (!Number.isFinite(value)) {
      return '—';
    }
    const abs = Math.abs(value);
    if (abs >= 1e12) {
      return `${(value / 1e12).toFixed(2).replace(/\.00$/, '')}T`;
    }
    if (abs >= 1e9) {
      return `${(value / 1e9).toFixed(2).replace(/\.00$/, '')}B`;
    }
    if (abs >= 1e6) {
      return `${(value / 1e6).toFixed(2).replace(/\.00$/, '')}M`;
    }
    return d3.format(',')(value);
  };

  const rows = tbody.selectAll('tr')
    .data(data)
    .enter()
    .append('tr')
    .attr('data-ticker', (d) => d.ticker);

  rows.append('td').text((d) => d.ticker);
  rows.append('td').text((d) => d.name);
  rows.append('td').text((d) => d.sector);
  rows.append('td').text((d) => formatMarketCap(d.marketCap));

  let selectedTicker = null;

  const selectTicker = (ticker) => {
    selectedTicker = ticker;
    node.classed('selected', (d) => d.ticker === ticker);
    rows.classed('selected', (d) => d.ticker === ticker);
    updateHistory(ticker);
  };

  node.on('click', (event, d) => {
    selectTicker(d.ticker);
  });

  rows.on('click', (event, d) => {
    selectTicker(d.ticker);
  });

  const historySvg = d3.select('#history-chart');
  const historyWidth = 640;
  const historyHeight = 160;
  const historyMargin = { top: 18, right: 18, bottom: 26, left: 46 };

  historySvg
    .attr('viewBox', `0 0 ${historyWidth} ${historyHeight}`)
    .attr('role', 'img')
    .attr('aria-label', 'Selected stock price history line chart.');

  const historyPlot = historySvg.append('g')
    .attr('transform', `translate(${historyMargin.left}, ${historyMargin.top})`);

  const innerWidth = historyWidth - historyMargin.left - historyMargin.right;
  const innerHeight = historyHeight - historyMargin.top - historyMargin.bottom;

  const xScale = d3.scaleTime().range([0, innerWidth]);
  const yScale = d3.scaleLinear().range([innerHeight, 0]);

  const xAxis = historyPlot.append('g')
    .attr('class', 'axis')
    .attr('transform', `translate(0, ${innerHeight})`);

  const yAxis = historyPlot.append('g')
    .attr('class', 'axis');

  const historyPath = historyPlot.append('path')
    .attr('class', 'history-line');

  const parseDate = d3.timeParse('%Y-%m-%d');
  const formatDate = d3.timeFormat('%Y-%m-%d');
  const formatPrice = d3.format(',.2f');

  const updateHistory = (ticker) => {
    const series = PRICE_HISTORY[ticker] || [];
    if (!series.length) {
      historyPath.attr('d', '');
      d3.select('#history-meta').text('No price history available.');
      return;
    }

    const points = series.map((d) => ({ date: parseDate(d[0]), close: d[1] }));

    xScale.domain(d3.extent(points, (d) => d.date));
    yScale.domain(d3.extent(points, (d) => d.close)).nice();

    xAxis.call(d3.axisBottom(xScale).ticks(4));
    yAxis.call(d3.axisLeft(yScale).ticks(4));

    historyPath
      .datum(points)
      .attr('d', d3.line()
        .x((d) => xScale(d.date))
        .y((d) => yScale(d.close))
      );

    const first = points[0];
    const last = points[points.length - 1];
    const change = ((last.close / first.close) - 1) * 100;
    const changeText = `${change >= 0 ? '+' : ''}${change.toFixed(2)}%`;

    d3.select('#history-meta').text(
      `${ticker} | ${formatDate(first.date)} to ${formatDate(last.date)} | Last close $${formatPrice(last.close)} | Total change ${changeText}`
    );
  };

  selectTicker(data[0].ticker);
})();
"""

js = template.replace('__STOCK_DATA__', stock_json).replace('__PRICE_HISTORY__', price_json)

with open(OUT_PATH, 'w', newline='\n') as f:
    f.write(js)

PY"}

